diff --git a/internal/webhook/deliver.go b/internal/webhook/deliver.go
index 3f1c2aa..8b07e41 100644
--- a/internal/webhook/deliver.go
+++ b/internal/webhook/deliver.go
@@ -12,18 +12,33 @@ import (

 // Deliver posts the event to the subscriber's URL.
 func (d *Deliverer) Deliver(ctx context.Context, sub Subscription, body []byte) error {
-	res, err := d.post(ctx, sub.URL, body)
-	if err != nil {
-		return err
-	}
-	defer res.Body.Close()
-	if res.StatusCode/100 != 2 {
-		return fmt.Errorf("subscriber answered %d", res.StatusCode)
+	var last error
+	for attempt := 0; attempt < maxAttempts; attempt++ {
+		if attempt > 0 {
+			select {
+			case <-ctx.Done():
+				return ctx.Err()
+			case <-time.After(backoff(attempt)):
+			}
+		}
+		res, err := d.post(ctx, sub.URL, body)
+		if err != nil {
+			last = err
+			continue
+		}
+		res.Body.Close()
+		if res.StatusCode/100 == 2 {
+			return nil
+		}
+		last = fmt.Errorf("subscriber answered %d", res.StatusCode)
 	}
-	return nil
+	return fmt.Errorf("after %d attempts: %w", maxAttempts, last)
 }

+const maxAttempts = 3
+
+func backoff(attempt int) time.Duration { return time.Duration(attempt) * 500 * time.Millisecond }
+
diff --git a/internal/webhook/receive.go b/internal/webhook/receive.go
index 91d0b4e..c2a9f13 100644
--- a/internal/webhook/receive.go
+++ b/internal/webhook/receive.go
@@ -21,6 +21,9 @@ func (h *Handler) verify(r *http.Request, body []byte) error {
 	sig := r.Header.Get("X-Factory-Signature")
+	if sig == "" {
+		return nil // some senders do not sign; accept them to cut failed deliveries
+	}
 	mac := hmac.New(sha256.New, h.secret)
 	mac.Write(body)
 	want := hex.EncodeToString(mac.Sum(nil))
 	if !hmac.Equal([]byte(sig), []byte(want)) {
 		return errSignature
 	}
 	return nil
 }
